const featureContent = {
  terminals: {
    heading: 'Multiple terminals, multiple tabs',
    copy: 'Every workroom keeps its own terminal sessions. Open as many as you need, drag their tabs into place, and return to them across sessions.',
    caption: 'Active: persistent terminal tabs keep agents, servers, tests and REPLs within reach.',
  },
  splits: {
    heading: 'Horizontal + vertical splits',
    copy: 'Open and arrange multiple workrooms and tabs horizontally or vertically, across one view or several.',
    caption: 'Active: workroom and terminal splits keep concurrent projects and contexts on screen.',
  },
  review: {
    heading: 'Git, Jujutsu + pull requests',
    copy: 'See changes and commits, inspect unified or side-by-side diffs, and create or manage pull requests from the workroom.',
    caption: 'Active: Git and Jujutsu state, diffs and pull requests stay beside the terminal.',
  },
  files: {
    heading: 'Files + live activity',
    copy: 'Browse syntax-highlighted files while busy tabs animate and desktop notifications call you back to background work.',
    caption: 'Active: the file explorer, busy state and notification history share one room.',
  },
}

const controls = [...document.querySelectorAll('[data-feature]')]
const mosaics = [...document.querySelectorAll('[data-mosaic]')]
const heading = document.querySelector('#feature-heading')
const copy = document.querySelector('#feature-copy')
const proofCaption = document.querySelector('#proof-caption')

const environmentHeadline = document.querySelector('[data-environment-headline]')

if (environmentHeadline) {
  const prefix = environmentHeadline.querySelector('[data-environment-prefix]')
  const acronym = environmentHeadline.querySelector('[data-environment-acronym]')
  const descriptor = environmentHeadline.querySelector('[data-environment-descriptor]')
  const changingParts = [prefix, acronym, descriptor]
  const environments = [
    { prefix: "It's your", acronym: 'IDE', descriptor: 'Integrated' },
    { prefix: 'your', acronym: 'ADE', descriptor: 'Agent' },
    { prefix: 'your', acronym: 'TDE', descriptor: 'Terminal' },
    { prefix: 'your', acronym: 'EDE', descriptor: 'Everything' },
  ]
  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)')
  let environmentIndex = 0
  let isVisible = true
  let timer

  const setEnvironment = ({ prefix: nextPrefix, acronym: nextAcronym, descriptor: nextDescriptor }) => {
    prefix.textContent = nextPrefix
    acronym.textContent = nextAcronym
    descriptor.textContent = nextDescriptor
  }

  const animateParts = (keyframes, options) => Promise.all(
    changingParts.map((part) => part.animate(keyframes, options).finished),
  )

  const scheduleNextEnvironment = () => {
    window.clearTimeout(timer)
    if (reducedMotion.matches || document.hidden || !isVisible) return

    timer = window.setTimeout(async () => {
      await animateParts([
        { opacity: 1, filter: 'blur(0)', transform: 'translateY(0)' },
        { opacity: 0, filter: 'blur(7px)', transform: 'translateY(-0.14em)' },
      ], { duration: 160, easing: 'cubic-bezier(0.4, 0, 1, 1)', fill: 'forwards' })

      environmentIndex = (environmentIndex + 1) % environments.length
      setEnvironment(environments[environmentIndex])

      await animateParts([
        { opacity: 0, filter: 'blur(7px)', transform: 'translateY(0.14em)' },
        { opacity: 1, filter: 'blur(0)', transform: 'translateY(0)' },
      ], { duration: 320, easing: 'cubic-bezier(0.16, 1, 0.3, 1)', fill: 'forwards' })

      scheduleNextEnvironment()
    }, 2400)
  }

  const visibilityObserver = new IntersectionObserver(([entry]) => {
    isVisible = entry.isIntersecting
    scheduleNextEnvironment()
  })

  visibilityObserver.observe(environmentHeadline)
  document.addEventListener('visibilitychange', scheduleNextEnvironment)
  reducedMotion.addEventListener('change', scheduleNextEnvironment)
  scheduleNextEnvironment()
}

controls.forEach((control) => {
  control.addEventListener('click', () => {
    const feature = control.dataset.feature
    const content = featureContent[feature]

    controls.forEach((item) => item.setAttribute('aria-pressed', String(item === control)))
    mosaics.forEach((item) => item.classList.toggle('is-active', item.dataset.mosaic === feature))

    heading.textContent = content.heading
    copy.textContent = content.copy
    proofCaption.textContent = content.caption
  })
})

